1	/**
2	 * Rendering an unhandled exception the way CPython does, plus the notice the
3	 * PyInstaller bootloader prints for the frozen script.
4	 *
5	 * The layout below was pinned against the reference binary, including the
6	 * cases where a doctored source file makes the offsets disagree with the code
7	 * object:
8	 *
9	 *   - the echoed line keeps trailing whitespace but loses its indent;
10	 *   - the caret indent is `startOffset - (len(rawLine) - len(echoedLine))`;
11	 *   - offsets recorded by the compiler are *byte* offsets, converted to
12	 *     character offsets against the line actually on disk, which also clamps
13	 *     them to the end of that line;
14	 *   - the caret row is omitted only when the expression spans the whole line.
15	 *
16	 * Lengths are counted in code points, matching Python's `len()` on `str`.
17	 */
18	
19	import { getLine } from './linecache.mjs';
20	import { writeStderr } from './sys.mjs';
21	
22	/** Exit status the interpreter uses for an unhandled exception. */
23	const UNHANDLED_EXCEPTION_STATUS = 1;
24	
25	/** Indent CPython uses for echoed source and caret rows. */
26	const SOURCE_INDENT = '    ';
27	
28	/**
29	 * `len(text)` for a Python `str`: a count of code points.
30	 *
31	 * @param {string} text
32	 * @returns {number}
33	 */
34	function codePointLength(text) {
35	  return Array.from(text).length;
36	}
37	
38	/**
39	 * `traceback._byte_offset_to_character_offset`: where a UTF-8 byte offset lands
40	 * once the line is measured in characters. Offsets past the end of the line
41	 * clamp to its length.
42	 *
43	 * @param {string} line
44	 * @param {number} byteOffset
45	 * @returns {number}
46	 */
47	function byteOffsetToCharacterOffset(line, byteOffset) {
48	  const encoded = Buffer.from(line, 'utf8');
49	  const prefix = new TextDecoder('utf-8').decode(encoded.subarray(0, byteOffset));
50	  return codePointLength(prefix);
51	}
52	
53	/**
54	 * The source and caret rows for one frame, or '' when the source is not
55	 * available from the working directory.
56	 *
57	 * @param {{file: string, line: number, colOffset?: number, endColOffset?: number}} frame
58	 * @returns {string}
59	 */
60	function formatFrameSource(frame) {
61	  const rawLine = getLine(frame.file, frame.line);
62	  if (rawLine === '') return '';
63	
64	  // The echoed line loses its indent and its newline, but keeps trailing space.
65	  const withoutNewline = rawLine.replace(/\r?\n$|\r$/, '');
66	  const echoed = withoutNewline.replace(/^\s+/, '');
67	  let out = `${SOURCE_INDENT}${echoed}\n`;
68	
69	  if (frame.colOffset === undefined || frame.endColOffset === undefined) return out;
70	
71	  const strippedCharacters = codePointLength(rawLine) - codePointLength(echoed);
72	  const startOffset = byteOffsetToCharacterOffset(rawLine, frame.colOffset) + 1;
73	  const endOffset = byteOffsetToCharacterOffset(rawLine, frame.endColOffset) + 1;
74	  const caretCount = endOffset - startOffset;
75	
76	  // Carets are shown only when the expression does not span the whole line.
77	  if (caretCount >= codePointLength(echoed)) return out;
78	
79	  const indent = Math.max(0, startOffset - strippedCharacters);
80	  out += `${SOURCE_INDENT}${' '.repeat(indent)}${'^'.repeat(Math.max(0, caretCount))}\n`;
81	  return out;
82	}
83	
84	/**
85	 * Render a traceback for an exception carrying `pythonType`, `message` and
86	 * `pythonFrames`.
87	 *
88	 * @param {{pythonType: string, message: string, pythonFrames: object[]}} error
89	 * @returns {string}
90	 */
91	export function formatTraceback(error) {
92	  let out = 'Traceback (most recent call last):\n';
93	  for (const frame of error.pythonFrames) {
94	    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
95	    out += formatFrameSource(frame);
96	  }
97	  return `${out}${error.pythonType}: ${error.message}\n`;
98	}
99	
100	/**
101	 * Print the traceback and flag the failing exit status.
102	 *
103	 * The status is set rather than forced through `process.exit` so nothing can
104	 * cut the diagnostic short.
105	 *
106	 * @param {{pythonType: string, message: string, pythonFrames: object[]}} error
107	 * @param {string} frozenScriptName name the bootloader reports
108	 */
109	export function reportUnhandledException(error, frozenScriptName) {
110	  writeStderr(formatTraceback(error));
111	  writeStderr(
112	    `[PYI-${process.pid}:ERROR] Failed to execute script ` +
113	      `'${frozenScriptName}' due to unhandled exception!\n`,
114	  );
115	  process.exitCode = UNHANDLED_EXCEPTION_STATUS;
116	}
