1	/**
2	 * CPython's `linecache`, as far as traceback rendering needs it.
3	 *
4	 * The frozen reference program records its frames with the *relative* filename
5	 * `test13.py`, so whether a traceback shows source lines depends on whether
6	 * such a file can be read from the current working directory and decoded as
7	 * UTF-8 — a file with undecodable bytes yields no source lines at all, exactly
8	 * as `tokenize.open` raising `UnicodeDecodeError` makes `updatecache` give up.
9	 */
10	
11	import { readFileSync } from 'node:fs';
12	
13	/** @type {Map<string, string[] | null>} */
14	const cache = new Map();
15	
16	/**
17	 * Split like `str.splitlines(keepends=True)` for the line endings that matter
18	 * in source files.
19	 *
20	 * @param {string} text
21	 * @returns {string[]}
22	 */
23	function splitKeepingEnds(text) {
24	  const lines = text.split(/(?<=\r\n|\n|\r)/);
25	  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
26	  return lines;
27	}
28	
29	/**
30	 * Read and cache a file's lines, or remember that it is unreadable.
31	 *
32	 * @param {string} filename
33	 * @returns {string[] | null}
34	 */
35	function getLines(filename) {
36	  if (!cache.has(filename)) {
37	    try {
38	      const bytes = readFileSync(filename);
39	      const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
40	      cache.set(filename, splitKeepingEnds(text));
41	    } catch {
42	      cache.set(filename, null);
43	    }
44	  }
45	  return cache.get(filename) ?? null;
46	}
47	
48	/**
49	 * `linecache.getline`: the requested line including its terminator, or the
50	 * empty string when unavailable.
51	 *
52	 * @param {string} filename
53	 * @param {number} lineno 1-based
54	 * @returns {string}
55	 */
56	export function getLine(filename, lineno) {
57	  const lines = getLines(filename);
58	  if (lines === null || lineno < 1 || lineno > lines.length) return '';
59	  return lines[lineno - 1];
60	}
