import { mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';

const ORIG = readFileSync('/workspace/dataset/test13.py', 'utf8');
const origLines = ORIG.split('\n'); // no keepends; index 0 == line 1

const base = '/tmp/t/cases';
rmSync(base, { recursive: true, force: true });
mkdirSync(base, { recursive: true });

/** build a file from a map of 1-based lineno -> replacement text (no newline) */
function doctor(name, replacements, opts = {}) {
  const lines = origLines.slice();
  for (const [n, text] of Object.entries(replacements)) {
    lines[Number(n) - 1] = text;
  }
  let text = lines.join('\n');
  if (opts.crlf) text = text.replace(/\n/g, '\r\n');
  const dir = `${base}/${name}`;
  mkdirSync(dir, { recursive: true });
  writeFileSync(`${dir}/test13.py`, opts.bytes ? Buffer.concat([Buffer.from(text, 'utf8'), opts.bytes]) : text);
  return dir;
}

function rawFile(name, buf) {
  const dir = `${base}/${name}`;
  mkdirSync(dir, { recursive: true });
  writeFileSync(`${dir}/test13.py`, buf);
  return dir;
}

// (a) real
doctor('a_real', {});
// (b) none
mkdirSync(`${base}/b_none`, { recursive: true });
// (c) too short
rawFile('c_short5', Buffer.from(origLines.slice(0, 5).join('\n') + '\n'));
rawFile('c_empty', Buffer.from(''));
rawFile('c_short12', Buffer.from(origLines.slice(0, 12).join('\n') + '\n')); // line 11,12 ok, 18 missing
// (d) blank relevant lines
doctor('d_blank', { 11: '', 12: '', 13: '', 18: '' });
doctor('d_ws_only', { 11: '    ', 12: '   ', 13: '  ', 18: ' ' });
// shorter than recorded column offset
doctor('d_tooshort', { 11: '    x', 12: '  y', 13: 'z', 18: 'q' });
// tabs indent
doctor('d_tabs', {
  11: '\t' + origLines[10].trimStart(),
  12: '\t' + origLines[11].trimStart(),
  13: '\t' + origLines[12].trimStart(),
  18: '\t' + origLines[17].trimStart(),
});
// deeper indent
doctor('d_deep', {
  11: '            ' + origLines[10].trimStart(),
  12: '            ' + origLines[11].trimStart(),
  13: '            ' + origLines[12].trimStart(),
  18: '            ' + origLines[17].trimStart(),
});
// no indent
doctor('d_noindent', {
  11: origLines[10].trimStart(),
  12: origLines[11].trimStart(),
  13: origLines[12].trimStart(),
  18: origLines[17].trimStart(),
});
// trailing whitespace
doctor('d_trailws', {
  11: origLines[10] + '     ',
  12: origLines[11] + '   ',
  13: origLines[12] + '  ',
  18: origLines[17] + '        ',
});
// trailing tab
doctor('d_trailtab', {
  11: origLines[10] + '\t\t',
  12: origLines[11] + '\t',
  13: origLines[12] + '\t',
  18: origLines[17] + '\t',
});
// multibyte UTF-8 before the failing expression (narrow, e.g. e-acute)
doctor('d_mb_narrow', {
  11: '    # éééé\n'.trimEnd(),
});
doctor('d_mb_narrow2', {
  11: '    aes = pyaes.AESModeOfOperationECB(args.key.encode())  # éééé',
  12: '    ciphertext = aes.encrypt(args.data.encode())  # ééé',
});
// multibyte BEFORE the expression, same line
doctor('d_mb_before', {
  11: '    aés = pyaes.AESModeOfOperationECB(args.key.encode())  # x',
  12: '    ciphertéxt = aes.encrypt(args.data.encode())  # x',
  13: '    plaintéxt = aes.decrypt(ciphertext)  # x',
  18: '    máin()',
});
// wide (CJK) chars before expression
doctor('d_wide_before', {
  11: '    # 漢字漢字 aes = pyaes.AESModeOfOperationECB(args.key.encode())',
  12: '    # 漢字漢 ciphertext = aes.encrypt(args.data.encode())',
  18: '    # 漢字 main()',
});
// wide chars only, expression absent
doctor('d_wide_only', { 11: '    漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字漢字' });
// expression spans whole line
doctor('d_spanwhole', {
  11: 'pyaes.AESModeOfOperationECB(args.key.encode())',
  12: 'aes.encrypt(args.data.encode())',
  18: 'main()',
});
// line exactly one char shorter than expression
doctor('d_almost', {
  11: 'pyaes.AESModeOfOperationECB(args.key.encode()',
  12: 'aes.encrypt(args.data.encode()',
  18: 'main(',
});
