doctor('d_vt', { 10: 'xY', 11: origLines[10] });
doctor('d_ff', { 10: 'x Y', 11: origLines[10] });
doctor('d_u2028', { 10: 'x Y', 11: origLines[10] });
doctor('d_nel', { 10: 'xY', 11: origLines[10] });
