rawFile('e_badutf8', Buffer.concat([Buffer.from(origLines.slice(0, 9).join('\n') + '\n'), Buffer.from([0xff, 0xfe, 0x0a]), Buffer.from(origLines.slice(10).join('\n') + '\n')]));
rawFile('e_badutf8_tail', Buffer.concat([Buffer.from(ORIG, 'utf8'), Buffer.from([0x80])]));
// utf-8 BOM
rawFile('e_bom', Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(ORIG, 'utf8')]));
// coding: latin-1 declaration with latin-1 bytes
rawFile('e_latin1', Buffer.concat([
  Buffer.from('# -*- coding: latin-1 -*-\n'),
  Buffer.from(origLines.slice(0, 10).join('\n') + '\n', 'utf8'),
  Buffer.from([0x20, 0x20, 0x23, 0x20, 0xe9, 0x0a]),
  Buffer.from(origLines.slice(11).join('\n') + '\n', 'utf8'),
]));
// no trailing newline at all on final line
rawFile('d_nonl', Buffer.from(ORIG.trimEnd()));
